---
	chain forward {
		type filter hook forward priority filter; policy drop;
		ct state vmap { established : accept, related : accept } comment "!fw4: Handle forwarded flows"
		iifname "br-lan" jump forward_lan comment "!fw4: Handle lan IPv4/IPv6 forward traffic"
		iifname "eth1" jump forward_lana comment "!fw4: Handle lana IPv4/IPv6 forward traffic"
		iifname "eth2" jump forward_lanb comment "!fw4: Handle lanb IPv4/IPv6 forward traffic"
--
	chain forward_lan {
		jump accept_to_wan comment "!fw4: Accept lan to wan forwarding"
		jump accept_to_lan
	}

	chain helper_lan {
--
	chain forward_wan {
		icmpv6 type { destination-unreachable, time-exceeded, echo-request, echo-reply } limit rate 1000/second burst 5 packets counter packets 0 bytes 0 accept comment "!fw4: Allow-ICMPv6-Forward"
		icmpv6 type . icmpv6 code { packet-too-big . 0, parameter-problem . 0, parameter-problem . 1 } limit rate 1000/second burst 5 packets counter packets 0 bytes 0 accept comment "!fw4: Allow-ICMPv6-Forward"
		meta l4proto esp counter packets 0 bytes 0 jump accept_to_lan comment "!fw4: Allow-IPSec-ESP"
		udp dport 500 counter packets 0 bytes 0 jump accept_to_lan comment "!fw4: Allow-ISAKMP"
		jump drop_to_wan
--
	chain forward_lana {
		meta nfproto ipv4 tcp dport 5432 counter packets 1 bytes 60 jump accept_to_lanb comment "!fw4: Allow-LanA-LanB-Postgres"
		jump reject_to_lana
	}

	chain helper_lana {
--
	chain forward_lanb {
		jump reject_to_lanb
	}

	chain helper_lanb {
	}
